<body>
  <main class="page">
    <header class="header">
      <div class="logo" aria-label="البنك">
        <span class="logo-mark">✓</span>
        <span>البنك</span>
      </div>
      <button class="back-button" type="button" aria-label="رجوع">‹</button>
    </header>

    <section class="content">
      <span class="step">التحقق من الهوية</span>
      <h1>أدخل رمز التحقق</h1>
      <p class="description">
        أرسلنا رمزًا مكونًا من 6 أرقام إلى الرقم
        <strong dir="ltr">+966 55 123 4567</strong>
      </p>

      <form id="verificationForm" novalidate>
        <div class="code-group" aria-label="حقول رمز التحقق">
          <input class="code-input" type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" aria-label="الرقم الأول">
          <input class="code-input" type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" aria-label="الرقم الثاني">
          <input class="code-input" type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" aria-label="الرقم الثالث">
          <input class="code-input" type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" aria-label="الرقم الرابع">
          <input class="code-input" type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" aria-label="الرقم الخامس">
          <input class="code-input" type="text" inputmode="numeric" maxlength="1" autocomplete="one-time-code" aria-label="الرقم السادس">
        </div>

        <p class="error" id="error" role="alert" aria-live="polite"></p>

        <div class="resend">
          <span>لم تصلك الرسالة؟</span>
          <button id="resendButton" type="button" disabled>إعادة الإرسال خلال 0:45</button>
        </div>

        <p class="support">
          هل تواجه مشكلة؟ <a href="tel:8000000000">تواصل مع خدمة العملاء</a>
        </p>

        <button class="verify-button" id="verifyButton" type="submit" disabled>تحقق</button>
      </form>
    </section>
  </main>

  <script>
    const inputs = Array.from(document.querySelectorAll(".code-input"));
    const form = document.getElementById("verificationForm");
    const error = document.getElementById("error");
    const verifyButton = document.getElementById("verifyButton");
    const resendButton = document.getElementById("resendButton");

    function updateCodeState() {
      inputs.forEach((input) => {
        input.value = input.value.replace(/\D/g, "").slice(0, 1);
        input.classList.toggle("filled", input.value !== "");
      });

      const complete = inputs.every((input) => input.value !== "");
      verifyButton.disabled = !complete;
      if (complete) error.textContent = "";
    }

    inputs.forEach((input, index) => {
      input.addEventListener("input", () => {
        input.value = input.value.replace(/\D/g, "").slice(0, 1);
        updateCodeState();
        if (input.value && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
      });

      input.addEventListener("keydown", (event) => {
        if (event.key === "Backspace" && !input.value && index > 0) {
          inputs[index - 1].focus();
        }
        if (event.key === "ArrowLeft" && index < inputs.length - 1) {
          inputs[index + 1].focus();
        }
        if (event.key === "ArrowRight" && index > 0) {
          inputs[index - 1].focus();
        }
      });

      input.addEventListener("paste", (event) => {
        const digits = (event.clipboardData.getData("text") || "").replace(/\D/g, "");
        if (digits) {
          event.preventDefault();
          digits.slice(0, 6).split("").forEach((digit, i) => {
            if (inputs[i]) inputs[i].value = digit;
          });
          updateCodeState();
          inputs[Math.min(digits.length, 6) - 1].focus();
        }
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      const code = inputs.map((input) => input.value).join("");

      if (code.length !== 6) {
        error.textContent = "يرجى إدخال الأرقام الستة كاملة.";
        return;
      }

      error.textContent = "تم التحقق من الرمز بنجاح.";
      verifyButton.textContent = "تم التحقق ✓";
      verifyButton.disabled = true;
    });

    let remaining = 45;
    const timer = setInterval(() => {
      remaining -= 1;
      const minutes = Math.floor(remaining / 60);
      const seconds = String(remaining % 60).padStart(2, "0");
      resendButton.textContent = `إعادة الإرسال خلال ${minutes}:${seconds}`;

      if (remaining <= 0) {
        clearInterval(timer);
        resendButton.disabled = false;
        resendButton.textContent = "إعادة إرسال الرمز";
      }
    }, 1000);

    resendButton.addEventListener("click", () => {
      remaining = 45;
      resendButton.disabled = true;
      resendButton.textContent = "إعادة الإرسال خلال 0:45";
      error.textContent = "تم إرسال رمز جديد.";
      inputs.forEach((input) => input.value = "");
      updateCodeState();
      inputs[0].focus();
    });

    inputs[0].focus();
  </script>
</body>
